ALTER TABLE "Game" ADD COLUMN "description" TEXT NOT NULL DEFAULT '';

UPDATE "Game" SET "description"='Ролевая игра с открытым миром в мрачном будущем. Исследуй Найт-Сити, выполняй задания и развивай своего персонажа.' WHERE "slug"='cyberpunk-2077';
