UPDATE "Game" SET "description"='Космическое приключение с процедурно генерируемыми планетами. Исследуй галактику, собирай ресурсы, строй базы и путешествуй.' WHERE "slug"='no-mans-sky';
UPDATE "Game" SET "description"='Приключенческий экшен о синоби в альтернативной Японии. Осваивай точные сражения на мечах, скрытность и вертикальное перемещение.' WHERE "slug"='sekiro';
