UPDATE "Game" SET "description"='Масштабная фэнтезийная RPG с открытым миром. Исследуй Скайрим, вступай в гильдии, осваивай магию и сражайся с драконами.' WHERE "slug"='the-elder-scrolls-v-skyrim';
